const nameEl=document.getElementById('name');
const countEl=document.getElementById('count');
const allEl=document.getElementById('allergies');
const err=document.getElementById('err');
const status=document.getElementById('status');
const list=document.getElementById('list');
const summary=document.getElementById('summary');
const send=document.getElementById('send');

function render(items){
  list.textContent='';
  let total=0;
  for(const it of items){
    total+=Number(it.count)||0;
    const li=document.createElement('li');
    li.setAttribute('data-hook','answer');
    const a=document.createElement('div');
    a.textContent=it.name+' — '+it.count+(Number(it.count)===1?' person':' people');
    const b=document.createElement('div');
    b.className='sub';
    b.textContent='Food allergies: '+(it.allergies||'none given');
    li.appendChild(a);li.appendChild(b);
    list.appendChild(li);
  }
  summary.textContent=items.length?(items.length+(items.length===1?' answer, ':' answers, ')+total+' people in total.'):'No answers yet.';
}

async function load(){
  try{
    const r=await tessera.call('data.read',{});
    const items=Array.isArray(r.data.guests)?r.data.guests:[];
    render(items);
  }catch(e){
    summary.textContent='The answers could not be loaded. Please reopen the tool.';
  }
}

async function submit(){
  status.textContent='';
  const missing=[];
  if(!nameEl.value.trim())missing.push('Name');
  if(!countEl.value.trim()||Number(countEl.value)<1)missing.push('How many people');
  if(missing.length){
    err.textContent='Please fill in: '+missing.join(', ')+'.';
    return;
  }
  err.textContent='';
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'guests',record:{name:nameEl.value.trim(),count:Number(countEl.value),allergies:allEl.value.trim()}}]});
    nameEl.value='';countEl.value='';allEl.value='';
    status.textContent='Answer saved.';
    await load();
  }catch(e){
    err.textContent='The answer could not be saved. What you typed is still here; please try again.';
  }
}
send.addEventListener('click',submit);
for(const el of [nameEl,countEl,allEl]){
  el.addEventListener('keydown',function(ev){if(ev.key==='Enter'){ev.preventDefault();submit();}});
}
load();
